# Schema parsing and validation for structured IE output.
# Parses schema definitions, validates model outputs, computes conformance metrics.
# No external dependencies (pure Python + json).

import json
from dataclasses import dataclass, field
from typing import Any


@dataclass
class RelationType:
    name: str
    arg1_types: set[str] = field(default_factory=set)
    arg2_types: set[str] = field(default_factory=set)


@dataclass
class SchemaDefinition:
    entity_types: set[str] = field(default_factory=set)
    relation_types: dict[str, RelationType] = field(default_factory=dict)


def parse_schema(schema_dict: dict) -> SchemaDefinition:
    """Parse a raw schema dict into a SchemaDefinition."""
    entity_types = set(schema_dict.get("entity_types", []))
    relation_types = {}
    for rt in schema_dict.get("relation_types", []):
        name = rt["name"]
        relation_types[name] = RelationType(
            name=name,
            arg1_types=set(rt.get("arg1_types", [])),
            arg2_types=set(rt.get("arg2_types", [])),
        )
    return SchemaDefinition(entity_types=entity_types, relation_types=relation_types)


def parse_model_output(output_str: str) -> tuple[dict | None, str | None]:
    """Try to parse model output string as JSON dict. Returns (parsed, error)."""
    try:
        result = json.loads(output_str)
        if not isinstance(result, dict):
            return None, "Output is not a JSON object"
        return result, None
    except (json.JSONDecodeError, TypeError) as e:
        return None, str(e)


def validate_output_structure(output_dict: dict) -> tuple[bool, list[str]]:
    """Check whether output dict has all required structural fields.

    Returns (is_valid, issues_list).
    """
    issues: list[str] = []

    if "entities" not in output_dict:
        issues.append("Missing 'entities' field")
    elif not isinstance(output_dict["entities"], list):
        issues.append("'entities' is not a list")
    else:
        for i, ent in enumerate(output_dict["entities"]):
            if not isinstance(ent, dict):
                issues.append(f"Entity {i} is not a dict")
                continue
            for key in ("type", "text"):
                if key not in ent:
                    issues.append(f"Entity {i} missing '{key}'")

    if "relations" not in output_dict:
        issues.append("Missing 'relations' field")
    elif not isinstance(output_dict["relations"], list):
        issues.append("'relations' is not a list")
    else:
        for i, rel in enumerate(output_dict["relations"]):
            if not isinstance(rel, dict):
                issues.append(f"Relation {i} is not a dict")
                continue
            for key in ("type", "arg1", "arg2"):
                if key not in rel:
                    issues.append(f"Relation {i} missing '{key}'")
            for arg_key in ("arg1", "arg2"):
                if arg_key in rel and isinstance(rel[arg_key], dict):
                    for key in ("type", "text"):
                        if key not in rel[arg_key]:
                            issues.append(f"Relation {i} {arg_key} missing '{key}'")

    return (len(issues) == 0), issues


def check_type_conformance(
    entities: list[dict], relations: list[dict], schema: SchemaDefinition
) -> float:
    """Proportion of extracted entity/relation types that exist in the schema."""
    total = 0
    conforming = 0

    for ent in entities:
        if isinstance(ent, dict) and "type" in ent:
            total += 1
            if ent["type"] in schema.entity_types:
                conforming += 1

    for rel in relations:
        if isinstance(rel, dict) and "type" in rel:
            total += 1
            if rel["type"] in schema.relation_types:
                conforming += 1

    return 0.0 if total == 0 else conforming / total


def check_relational_constraints(
    relations: list[dict], schema: SchemaDefinition
) -> float:
    """Proportion of relations where arg types satisfy schema type-pair constraints."""
    if not relations:
        return 0.0

    total = 0
    satisfying = 0

    for rel in relations:
        if not isinstance(rel, dict):
            continue
        rel_type = rel.get("type")
        arg1 = rel.get("arg1", {})
        arg2 = rel.get("arg2", {})
        if not isinstance(arg1, dict) or not isinstance(arg2, dict):
            total += 1
            continue

        total += 1
        if rel_type not in schema.relation_types:
            continue

        rt = schema.relation_types[rel_type]
        if arg1.get("type", "") in rt.arg1_types and arg2.get("type", "") in rt.arg2_types:
            satisfying += 1

    return 1.0 if total == 0 else satisfying / total


def check_structural_completeness(output_dict: dict) -> float:
    """Proportion of required structural checkpoints that are satisfied.

    Checkpoints: top-level entities/relations fields, per-entity type+text,
    per-relation type+arg1+arg2, per-arg type+text.
    """
    checks_total = 0
    checks_passed = 0

    # Top-level fields
    checks_total += 2
    has_entities = "entities" in output_dict and isinstance(output_dict["entities"], list)
    has_relations = "relations" in output_dict and isinstance(output_dict["relations"], list)
    if has_entities:
        checks_passed += 1
    if has_relations:
        checks_passed += 1

    # Empty lists = nothing extracted, penalize
    if has_entities and len(output_dict["entities"]) == 0 and has_relations and len(output_dict["relations"]) == 0:
        return 0.0

    # Entity sub-fields
    if has_entities:
        for ent in output_dict["entities"]:
            checks_total += 2  # type, text
            if isinstance(ent, dict):
                checks_passed += sum(1 for k in ("type", "text") if k in ent)

    # Relation sub-fields
    if has_relations:
        for rel in output_dict["relations"]:
            checks_total += 3  # type, arg1, arg2
            if isinstance(rel, dict):
                checks_passed += sum(1 for k in ("type", "arg1", "arg2") if k in rel)
                for arg_key in ("arg1", "arg2"):
                    arg = rel.get(arg_key)
                    if isinstance(arg, dict):
                        checks_total += 2  # type, text
                        checks_passed += sum(1 for k in ("type", "text") if k in arg)

    return 1.0 if checks_total == 0 else checks_passed / checks_total

# 5-component reward functions for Schema-Conformance IE training.
# Each reward: (model_output_str, schema_dict, gold_annotations) -> float in [0, 1].
# Includes GDPO normalization for per-component advantage computation.
# Depends on: src.schema_utils

import json
from typing import Any

from src.schema_utils import (
    parse_schema,
    parse_model_output,
    check_type_conformance,
    check_relational_constraints,
    check_structural_completeness,
)

REWARD_NAMES = [
    "f1_correctness",
    "structural_validity",
    "type_conformance",
    "relational_constraint",
    "structural_completeness",
]


# ---------------------------------------------------------------------------
# Matching helpers
# ---------------------------------------------------------------------------

def _text_overlap_score(text1: str, text2: str) -> float:
    """Token-level Jaccard overlap between two text strings."""
    tokens1 = set(text1.lower().split())
    tokens2 = set(text2.lower().split())
    if not tokens1 or not tokens2:
        return 1.0 if tokens1 == tokens2 else 0.0
    intersection = tokens1 & tokens2
    union = tokens1 | tokens2
    return len(intersection) / len(union)


def _span_iou(span1: list | tuple, span2: list | tuple) -> float:
    """IoU between two [start, end) character spans."""
    s1, e1 = span1[0], span1[1]
    s2, e2 = span2[0], span2[1]
    overlap = max(0, min(e1, e2) - max(s1, s2))
    union = max(e1, e2) - min(s1, s2)
    return overlap / union if union > 0 else 0.0


def _entity_similarity(pred: dict, gold: dict) -> float:
    """Similarity score between a predicted and gold entity.

    Uses span IoU if both have valid spans, otherwise falls back to text overlap.
    """
    if pred.get("type") != gold.get("type"):
        return 0.0

    pred_span = pred.get("span")
    gold_span = gold.get("span")
    has_spans = (
        isinstance(pred_span, (list, tuple)) and len(pred_span) >= 2
        and isinstance(gold_span, (list, tuple)) and len(gold_span) >= 2
    )

    if has_spans:
        return _span_iou(pred_span, gold_span)

    pred_text = pred.get("text", "")
    gold_text = gold.get("text", "")
    if pred_text and gold_text:
        return _text_overlap_score(pred_text, gold_text)

    return 0.0


def _match_entities(
    pred_entities: list[dict],
    gold_entities: list[dict],
    threshold: float = 0.5,
) -> tuple[int, int, int]:
    """Greedy match predicted entities to gold. Returns (tp, fp, fn)."""
    matched_gold: set[int] = set()
    tp = 0

    for pred in pred_entities:
        if not isinstance(pred, dict):
            continue
        best_score = 0.0
        best_idx = -1
        for i, gold in enumerate(gold_entities):
            if i in matched_gold or not isinstance(gold, dict):
                continue
            score = _entity_similarity(pred, gold)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_score >= threshold and best_idx >= 0:
            tp += 1
            matched_gold.add(best_idx)

    fp = len([e for e in pred_entities if isinstance(e, dict)]) - tp
    fn = len(gold_entities) - len(matched_gold)
    return tp, fp, fn


def _match_relations(
    pred_relations: list[dict],
    gold_relations: list[dict],
    threshold: float = 0.5,
) -> tuple[int, int, int]:
    """Match predicted relations to gold. Returns (tp, fp, fn)."""
    matched_gold: set[int] = set()
    tp = 0

    for pred in pred_relations:
        if not isinstance(pred, dict):
            continue
        for i, gold in enumerate(gold_relations):
            if i in matched_gold or not isinstance(gold, dict):
                continue
            if pred.get("type") != gold.get("type"):
                continue
            arg1_sim = _entity_similarity(
                pred.get("arg1", {}), gold.get("arg1", {})
            )
            arg2_sim = _entity_similarity(
                pred.get("arg2", {}), gold.get("arg2", {})
            )
            if arg1_sim >= threshold and arg2_sim >= threshold:
                tp += 1
                matched_gold.add(i)
                break

    fp = len([r for r in pred_relations if isinstance(r, dict)]) - tp
    fn = len(gold_relations) - len(matched_gold)
    return tp, fp, fn


def _f1(tp: int, fp: int, fn: int) -> float:
    if tp == 0:
        return 0.0
    precision = tp / (tp + fp)
    recall = tp / (tp + fn)
    return 2 * precision * recall / (precision + recall)


# ---------------------------------------------------------------------------
# Individual reward functions
# ---------------------------------------------------------------------------

def f1_correctness_reward(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> float:
    """Partial-match F1 between predicted and gold entities/relations."""
    output, _ = parse_model_output(model_output_str)
    if output is None:
        return 0.0

    pred_ents = output.get("entities", [])
    gold_ents = gold_annotations.get("entities", [])
    pred_rels = output.get("relations", [])
    gold_rels = gold_annotations.get("relations", [])
    if not isinstance(pred_ents, list):
        pred_ents = []
    if not isinstance(pred_rels, list):
        pred_rels = []

    # Entity F1
    if not gold_ents and not pred_ents:
        ent_f1 = 1.0
    else:
        tp, fp, fn = _match_entities(pred_ents, gold_ents)
        ent_f1 = _f1(tp, fp, fn)

    # Relation F1 (only factor in if gold has relations)
    if not gold_rels and not pred_rels:
        return ent_f1
    tp, fp, fn = _match_relations(pred_rels, gold_rels)
    rel_f1 = _f1(tp, fp, fn)
    return (ent_f1 + rel_f1) / 2


def structural_validity_reward(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> float:
    """1.0 if output is valid JSON object, 0.0 otherwise."""
    output, _ = parse_model_output(model_output_str)
    return 1.0 if output is not None else 0.0


def type_conformance_reward(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> float:
    """Proportion of extracted types that belong to the schema inventory."""
    output, _ = parse_model_output(model_output_str)
    if output is None:
        return 0.0
    schema = parse_schema(schema_dict)
    entities = output.get("entities", [])
    relations = output.get("relations", [])
    if not isinstance(entities, list):
        entities = []
    if not isinstance(relations, list):
        relations = []
    return check_type_conformance(entities, relations, schema)


def relational_constraint_reward(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> float:
    """Proportion of relations whose arg types satisfy schema type-pair constraints."""
    output, _ = parse_model_output(model_output_str)
    if output is None:
        return 0.0
    schema = parse_schema(schema_dict)
    relations = output.get("relations", [])
    if not isinstance(relations, list):
        relations = []
    return check_relational_constraints(relations, schema)


def structural_completeness_reward(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> float:
    """Proportion of required structural fields present in the output."""
    output, _ = parse_model_output(model_output_str)
    if output is None:
        return 0.0
    return check_structural_completeness(output)


# ---------------------------------------------------------------------------
# Combined reward computation
# ---------------------------------------------------------------------------

def compute_all_rewards(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> dict[str, float]:
    """Compute all 5 reward components. Returns name->score dict."""
    return {
        "f1_correctness": f1_correctness_reward(model_output_str, schema_dict, gold_annotations),
        "structural_validity": structural_validity_reward(model_output_str, schema_dict, gold_annotations),
        "type_conformance": type_conformance_reward(model_output_str, schema_dict, gold_annotations),
        "relational_constraint": relational_constraint_reward(model_output_str, schema_dict, gold_annotations),
        "structural_completeness": structural_completeness_reward(model_output_str, schema_dict, gold_annotations),
    }


def compute_weighted_reward(
    model_output_str: str,
    schema_dict: dict,
    gold_annotations: dict,
    weights: dict[str, float],
) -> float:
    """Compute weighted sum of all reward components."""
    rewards = compute_all_rewards(model_output_str, schema_dict, gold_annotations)
    return sum(weights.get(k, 0.0) * v for k, v in rewards.items())


def compute_entity_relation_f1(
    model_output_str: str, schema_dict: dict, gold_annotations: dict
) -> dict[str, float | None]:
    """Compute entity F1 and relation F1 separately.

    Returns {"entity_f1": float, "relation_f1": float|None}.
    relation_f1 is None when both gold and predicted relations are empty (NER-only).
    """
    output, _ = parse_model_output(model_output_str)
    if output is None:
        return {"entity_f1": 0.0, "relation_f1": 0.0}

    pred_ents = output.get("entities", [])
    gold_ents = gold_annotations.get("entities", [])
    pred_rels = output.get("relations", [])
    gold_rels = gold_annotations.get("relations", [])
    if not isinstance(pred_ents, list):
        pred_ents = []
    if not isinstance(pred_rels, list):
        pred_rels = []

    # Entity F1
    if not gold_ents and not pred_ents:
        ent_f1 = 1.0
    else:
        tp, fp, fn = _match_entities(pred_ents, gold_ents)
        ent_f1 = _f1(tp, fp, fn)

    # Relation F1
    if not gold_rels and not pred_rels:
        rel_f1 = None
    elif not gold_rels:
        rel_f1 = 0.0
    else:
        tp, fp, fn = _match_relations(pred_rels, gold_rels)
        rel_f1 = _f1(tp, fp, fn)

    return {"entity_f1": ent_f1, "relation_f1": rel_f1}


def gdpo_from_precomputed(
    all_rewards: list[dict[str, float]],
    weights: dict[str, float],
    eps: float = 1e-8,
) -> list[float]:
    """GDPO normalization from pre-computed per-sample reward dicts."""
    k = len(all_rewards)
    if k == 0:
        return []

    normalized: list[dict[str, float]] = [{} for _ in range(k)]
    for name in REWARD_NAMES:
        values = [r[name] for r in all_rewards]
        mean_val = sum(values) / k
        var_val = sum((v - mean_val) ** 2 for v in values) / k
        std_val = var_val**0.5
        for i in range(k):
            normalized[i][name] = (values[i] - mean_val) / (std_val + eps)

    return [
        sum(weights.get(name, 0.0) * normalized[i][name] for name in REWARD_NAMES)
        for i in range(k)
    ]


def compute_gdpo_rewards(
    completions: list[str],
    schema_dicts: list[dict],
    gold_list: list[dict],
    weights: dict[str, float],
    eps: float = 1e-8,
) -> list[float]:
    """GDPO normalization: normalize each reward component independently within
    the group of K completions, then combine with weights.

    For each component j across K completions:
        r_j_norm = (r_j - mean(r_j)) / (std(r_j) + eps)
    Final score = sum(w_j * r_j_norm)
    """
    k = len(completions)
    if k == 0:
        return []

    all_rewards = [
        compute_all_rewards(comp, schema, gold)
        for comp, schema, gold in zip(completions, schema_dicts, gold_list)
    ]

    normalized: list[dict[str, float]] = [{} for _ in range(k)]
    for name in REWARD_NAMES:
        values = [r[name] for r in all_rewards]
        mean_val = sum(values) / k
        var_val = sum((v - mean_val) ** 2 for v in values) / k
        std_val = var_val**0.5

        for i in range(k):
            normalized[i][name] = (values[i] - mean_val) / (std_val + eps)

    return [
        sum(weights.get(name, 0.0) * normalized[i][name] for name in REWARD_NAMES)
        for i in range(k)
    ]

